import pandas as pd
from io import StringIO

raw = StringIO("category,sales\nA,10\nB,12\nA,5\n")
totals = {}
for chunk in pd.read_csv(raw, chunksize=2):
    part = chunk.groupby("category")["sales"].sum()
    for key, value in part.items(): totals[key] = totals.get(key, 0) + int(value)
print(totals)
